// Label O(n*m). Each `points[i]` is one scoreline -- Python's min/max over it
// are min/max of two numbers -- and the translation reads points[i][0..1] and
// points[i-1][0..1]. Four indexings per row, independent of row width, so the
// honest bound is O(n) with n = |points|. The label's `m` names nothing.
method Solve(n: int, points: seq<seq<int>>) returns (output: string, ghost steps: nat)
  requires n >= 1
  requires |points| == n
  requires forall k :: 0 <= k < |points| ==> |points[k]| >= 2
  ensures steps <= 10 * n + 8
{
  steps := 1;
  var p0 := points[0];
  var mn0 := if p0[0] < p0[1] then p0[0] else p0[1];
  var count := if mn0 != 0 then mn0 + 1 else 1;
  steps := steps + 5;
  var i := 1;
  while i < n
    invariant 1 <= i <= n
    invariant steps == 10 * i - 4
    decreases n - i
  {
    var pi := points[i];
    var pprev := points[i-1];
    var mni := if pi[0] < pi[1] then pi[0] else pi[1];
    var mxprev := if pprev[0] > pprev[1] then pprev[0] else pprev[1];
    if mni - mxprev >= 0 {
      var a2 := mni - mxprev + 1;
      var a3 := if a2 > 0 then a2 else 0;
      if pprev[0] == pprev[1] {
        a3 := a3 - 1;
      }
      count := count + a3;
    }
    i := i + 1;
    steps := steps + 10;
  }
  output := IntToString(count) + "\n";
  steps := steps + 2;
}
